pjrt_protocol_smoke.source:
// Temporary low-level smoke for PJRT_Executable_OptimizedProgram (patches 15+16).
// Not part of the repository test suite. Drives the built plugin through the
// pinned PJRT C API header only: argument validation, the two-call size
// protocol, undersized-buffer refusal without writes, exact copy without
// overrun, cache stability, mps.mhlo.* publication, published-program
// recompilation, and unknown-target refusal. Nothing is executed.
//
// Build and run (after the plugin build; X = the locked XLA source tree):
//   c++ -std=c++17 -O1 -I"$X" pjrt_protocol_smoke.cc -o pjrt_protocol_smoke
//   ./pjrt_protocol_smoke /path/to/libpjrt_plugin_mps.dylib
// Exit status 0 and a final "PASS" line mean every check held.

#include <dlfcn.h>

#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "xla/pjrt/c/pjrt_c_api.h"

namespace {

const PJRT_Api* api = nullptr;
int failures = 0;

void Check(bool ok, const std::string& what) {
    std::printf("%s %s\n", ok ? "ok  " : "FAIL", what.c_str());
    if (!ok)
        ++failures;
}

// Consumes `error`; returns its code (or -1 for success) and message.
int Consume(PJRT_Error* error, std::string* message = nullptr) {
    if (!error)
        return -1;
    PJRT_Error_GetCode_Args code{};
    code.struct_size = PJRT_Error_GetCode_Args_STRUCT_SIZE;
    code.error = error;
    PJRT_Error* code_error = api->PJRT_Error_GetCode(&code);
    int result = code_error ? -2 : static_cast<int>(code.code);
    if (message) {
        PJRT_Error_Message_Args text{};
        text.struct_size = PJRT_Error_Message_Args_STRUCT_SIZE;
        text.error = error;
        api->PJRT_Error_Message(&text);
        message->assign(text.message, text.message_size);
    }
    PJRT_Error_Destroy_Args destroy{};
    destroy.struct_size = PJRT_Error_Destroy_Args_STRUCT_SIZE;
    destroy.error = error;
    api->PJRT_Error_Destroy(&destroy);
    return result;
}

PJRT_LoadedExecutable* Compile(PJRT_Client* client, const std::string& text, int* code,
                               std::string* message) {
    PJRT_Program program{};
    program.struct_size = PJRT_Program_STRUCT_SIZE;
    program.code = const_cast<char*>(text.data());
    program.code_size = text.size();
    program.format = "mlir";
    program.format_size = 4;
    PJRT_Client_Compile_Args args{};
    args.struct_size = PJRT_Client_Compile_Args_STRUCT_SIZE;
    args.client = client;
    args.program = &program;
    *code = Consume(api->PJRT_Client_Compile(&args), message);
    return args.executable;
}

PJRT_Executable* ExecutableOf(PJRT_LoadedExecutable* loaded) {
    PJRT_LoadedExecutable_GetExecutable_Args args{};
    args.struct_size = PJRT_LoadedExecutable_GetExecutable_Args_STRUCT_SIZE;
    args.loaded_executable = loaded;
    Check(Consume(api->PJRT_LoadedExecutable_GetExecutable(&args)) == -1, "GetExecutable");
    return args.executable;
}

void Destroy(PJRT_LoadedExecutable* loaded) {
    PJRT_LoadedExecutable_Destroy_Args args{};
    args.struct_size = PJRT_LoadedExecutable_Destroy_Args_STRUCT_SIZE;
    args.executable = loaded;
    Check(Consume(api->PJRT_LoadedExecutable_Destroy(&args)) == -1, "LoadedExecutable_Destroy");
}

struct Query {
    int code = -1;
    std::string format;
    size_t size = 0;
};

Query OptimizedProgram(PJRT_Executable* executable, char* buffer, size_t buffer_size,
                       size_t args_size = PJRT_Executable_OptimizedProgram_Args_STRUCT_SIZE,
                       size_t program_size = PJRT_Program_STRUCT_SIZE, bool null_program = false) {
    PJRT_Program program{};
    program.struct_size = program_size;
    program.code = buffer;
    program.code_size = buffer_size;
    PJRT_Executable_OptimizedProgram_Args args{};
    args.struct_size = args_size;
    args.executable = executable;
    args.program = null_program ? nullptr : &program;
    Query query;
    query.code = Consume(api->PJRT_Executable_OptimizedProgram(&args));
    if (query.code == -1)
        query.format.assign(program.format, program.format_size);
    query.size = program.code_size;
    return query;
}

// Size query then exact fill, the protocol XLA's PjRtCApiExecutable uses.
std::string Published(PJRT_Executable* executable) {
    Query size = OptimizedProgram(executable, nullptr, 0);
    if (size.code != -1)
        return {};
    std::string text(size.size, '\0');
    Query fill = OptimizedProgram(executable, text.data(), text.size());
    return fill.code == -1 ? text : std::string{};
}

const char* const kProgram = R"(module @smoke {
  func.func public @main(%arg0: tensor<4xf32>) -> (tensor<4xf32>, tensor<4xf32>) {
    %0 = stablehlo.custom_call @mhlo.sinh(%arg0) {api_version = 4 : i32, backend_config = {}} : (tensor<4xf32>) -> tensor<4xf32>
    %1 = stablehlo.add %0, %arg0 : tensor<4xf32>
    return %0, %1 : tensor<4xf32>, tensor<4xf32>
  }
}
)";

const char* const kUnknown = R"(module @refused {
  func.func public @main(%arg0: tensor<4xf32>) -> tensor<4xf32> {
    %0 = stablehlo.custom_call @mps.mhlo.not_a_target(%arg0) {api_version = 4 : i32, backend_config = {}} : (tensor<4xf32>) -> tensor<4xf32>
    return %0 : tensor<4xf32>
  }
}
)";

}  // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s libpjrt_plugin_mps.dylib\n", argv[0]);
        return 2;
    }
    void* library = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
    if (!library) {
        std::fprintf(stderr, "dlopen: %s\n", dlerror());
        return 2;
    }
    using GetApi = const PJRT_Api* (*)();
    auto get_api = reinterpret_cast<GetApi>(dlsym(library, "GetPjrtApi"));
    api = get_api ? get_api() : nullptr;
    if (!api) {
        std::fprintf(stderr, "GetPjrtApi missing\n");
        return 2;
    }
    if (api->PJRT_Plugin_Initialize) {
        PJRT_Plugin_Initialize_Args init{};
        init.struct_size = PJRT_Plugin_Initialize_Args_STRUCT_SIZE;
        Check(Consume(api->PJRT_Plugin_Initialize(&init)) == -1, "Plugin_Initialize");
    }
    PJRT_Client_Create_Args create{};
    create.struct_size = PJRT_Client_Create_Args_STRUCT_SIZE;
    Check(Consume(api->PJRT_Client_Create(&create)) == -1 && create.client, "Client_Create");
    PJRT_Client* client = create.client;

    int code = 0;
    std::string message;
    PJRT_LoadedExecutable* loaded = Compile(client, kProgram, &code, &message);
    Check(code == -1 && loaded, "compile mhlo.sinh program: " + message);
    PJRT_Executable* executable = ExecutableOf(loaded);

    // Invalid arguments are refused without touching the executable.
    Check(OptimizedProgram(executable, nullptr, 0, 0).code == PJRT_Error_Code_INVALID_ARGUMENT,
          "undersized args struct -> INVALID_ARGUMENT");
    Check(OptimizedProgram(nullptr, nullptr, 0).code == PJRT_Error_Code_INVALID_ARGUMENT,
          "null executable -> INVALID_ARGUMENT");
    Check(OptimizedProgram(executable, nullptr, 0, PJRT_Executable_OptimizedProgram_Args_STRUCT_SIZE,
                           PJRT_Program_STRUCT_SIZE, true)
                  .code == PJRT_Error_Code_INVALID_ARGUMENT,
          "null program -> INVALID_ARGUMENT");
    Check(OptimizedProgram(executable, nullptr, 0, PJRT_Executable_OptimizedProgram_Args_STRUCT_SIZE,
                           0)
                  .code == PJRT_Error_Code_INVALID_ARGUMENT,
          "undersized program struct -> INVALID_ARGUMENT");

    // Two-call protocol.
    Query size = OptimizedProgram(executable, nullptr, 0);
    Check(size.code == -1 && size.format == "mlir" && size.size > 0, "size query: format mlir");
    const size_t n = size.size;

    constexpr char kGuard = '\x5a';
    constexpr size_t kSlack = 64;
    std::vector<char> small(n - 1 + kSlack, kGuard);
    Query undersized = OptimizedProgram(executable, small.data(), n - 1);
    bool untouched = true;
    for (char c : small)
        untouched = untouched && c == kGuard;
    Check(undersized.code == PJRT_Error_Code_INVALID_ARGUMENT && untouched,
          "undersized buffer -> INVALID_ARGUMENT, nothing written");

    std::vector<char> exact(n + kSlack, kGuard);
    Query fill = OptimizedProgram(executable, exact.data(), n);
    bool guarded = true;
    for (size_t i = n; i < exact.size(); ++i)
        guarded = guarded && exact[i] == kGuard;
    Check(fill.code == -1 && fill.size == n && fill.format == "mlir" && guarded,
          "exact fill: n bytes, no overrun");
    std::string text(exact.data(), n);
    std::vector<char> larger(2 * n, kGuard);
    Query roomy = OptimizedProgram(executable, larger.data(), larger.size());
    Check(roomy.code == -1 && roomy.size == n && std::string(larger.data(), n) == text &&
              larger[n] == kGuard,
          "larger buffer: same n bytes, code_size reports n");
    Check(Published(executable) == text, "repeated query is byte-identical");

    Check(text.find("@mps.mhlo.sinh") != std::string::npos &&
              text.find("@mhlo.sinh") == std::string::npos,
          "admitted mhlo.sinh published as mps.mhlo.sinh");
    Check(text.find("api_version = 4") != std::string::npos,
          "published custom call keeps its attributes");

    // The published program compiles again and publishes identically.
    PJRT_LoadedExecutable* again = Compile(client, text, &code, &message);
    Check(code == -1 && again, "published program recompiles: " + message);
    if (again) {
        Check(Published(ExecutableOf(again)) == text, "republished program is identical");
        Destroy(again);
    }

    // Unknown published-namespace targets stay refused, quoted as written.
    PJRT_LoadedExecutable* refused = Compile(client, kUnknown, &code, &message);
    Check(!refused && code == PJRT_Error_Code_UNIMPLEMENTED &&
              message.find("'mps.mhlo.not_a_target'") != std::string::npos,
          "unknown mps.mhlo target refused: " + message);

    Destroy(loaded);
    PJRT_Client_Destroy_Args destroy{};
    destroy.struct_size = PJRT_Client_Destroy_Args_STRUCT_SIZE;
    destroy.client = client;
    Check(Consume(api->PJRT_Client_Destroy(&destroy)) == -1, "Client_Destroy");

    std::printf("%s\n", failures ? "FAIL" : "PASS");
    return failures ? 1 : 0;
}
